/**
 * Event Bus — in-memory publish/subscribe implementation.
 * Services publish events here; other services subscribe to react to them.
 * No service imports another service directly; all cross-service communication
 * flows through this module (ADR-001).
 */

type EventCallback = (payload: unknown) => void;

export class EventBus {
  private readonly subscribers = new Map<string, EventCallback[]>();

  /**
   * Subscribe to an event. Multiple subscribers per event are supported.
   */
  subscribe(event: string, callback: EventCallback): void {
    const existing = this.subscribers.get(event) ?? [];
    existing.push(callback);
    this.subscribers.set(event, existing);
  }

  /**
   * Publish an event to all registered subscribers.
   * Subscribers are called synchronously in registration order.
   */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        // Isolate subscriber failures so one bad subscriber cannot break others
        console.error(`[EventBus] Error in subscriber for "${event}":`, err);
      }
    }
  }
}

// Singleton instance shared across the whole application
export const eventBus = new EventBus();

/**
 * User Service — owns all user data.
 * Exposes plain TypeScript methods; no HTTP handling here.
 * Publishes no events and subscribes to none.
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export type CreateUserInput = Omit<User, "id">;
export type UpdateUserInput = Partial<Omit<User, "id">>;

export class UserService {
  private readonly store = new Map<string, User>();

  create(input: CreateUserInput): User {
    if (!input.name || !input.email) {
      throw new Error("name and email are required");
    }
    const user: User = {
      id: randomUUID(),
      name: input.name.trim(),
      email: input.email.trim(),
    };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new Error(`User not found: ${id}`);
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: UpdateUserInput): User {
    const user = this.getById(id);
    const updated: User = {
      ...user,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.email !== undefined ? { email: input.email.trim() } : {}),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`User not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Project Service — owns all project data.
 * Exposes plain TypeScript methods; no HTTP handling here.
 * Publishes no events and subscribes to none.
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type CreateProjectInput = Omit<Project, "id" | "memberIds"> & {
  memberIds?: string[];
};
export type UpdateProjectInput = Partial<Omit<Project, "id" | "memberIds">>;

export class ProjectService {
  private readonly store = new Map<string, Project>();

  create(input: CreateProjectInput): Project {
    if (!input.name) throw new Error("name is required");
    const project: Project = {
      id: randomUUID(),
      name: input.name.trim(),
      description: (input.description ?? "").trim(),
      memberIds: input.memberIds ? [...input.memberIds] : [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) throw new Error(`Project not found: ${id}`);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: UpdateProjectInput): Project {
    const project = this.getById(id);
    const updated: Project = {
      ...project,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.description !== undefined
        ? { description: input.description.trim() }
        : {}),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Project not found: ${id}`);
    this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (project.memberIds.includes(userId)) {
      throw new Error(`User ${userId} is already a member of project ${projectId}`);
    }
    const updated: Project = {
      ...project,
      memberIds: [...project.memberIds, userId],
    };
    this.store.set(projectId, updated);
    return updated;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (!project.memberIds.includes(userId)) {
      throw new Error(`User ${userId} is not a member of project ${projectId}`);
    }
    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((mid) => mid !== userId),
    };
    this.store.set(projectId, updated);
    return updated;
  }
}

/**
 * Task Service — owns all task data.
 * Publishes "task.assigned" and "task.statusChanged" events via the Event Bus.
 * Status transitions are forward-only: todo → in-progress → done (ADR-001).
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export type CreateTaskInput = {
  title: string;
  description?: string;
  projectId: string;
  assigneeId?: string;
  status?: TaskStatus;
};

export type UpdateTaskInput = Partial<
  Pick<Task, "title" | "description">
>;

// Ordered tuple defines valid forward transitions
const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

function statusIndex(s: TaskStatus): number {
  return STATUS_ORDER.indexOf(s);
}

// Event payload shapes
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export class TaskService {
  private readonly store = new Map<string, Task>();
  private readonly bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(input: CreateTaskInput): Task {
    if (!input.title) throw new Error("title is required");
    if (!input.projectId) throw new Error("projectId is required");

    const task: Task = {
      id: randomUUID(),
      title: input.title.trim(),
      description: (input.description ?? "").trim(),
      status: input.status ?? "todo",
      assigneeId: input.assigneeId ?? null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    return task;
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(id: string, input: UpdateTaskInput): Task {
    const task = this.getById(id);
    const updated: Task = {
      ...task,
      ...(input.title !== undefined ? { title: input.title.trim() } : {}),
      ...(input.description !== undefined
        ? { description: input.description.trim() }
        : {}),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Task not found: ${id}`);
    this.store.delete(id);
  }

  assign(id: string, assigneeId: string): Task {
    const task = this.getById(id);
    const updated: Task = { ...task, assigneeId };
    this.store.set(id, updated);

    const payload: TaskAssignedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
    };
    this.bus.publish("task.assigned", payload);

    return updated;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getById(id);
    const oldIndex = statusIndex(task.status);
    const newIndex = statusIndex(newStatus);

    if (newIndex === -1) {
      throw new Error(`Invalid status: ${newStatus}`);
    }
    if (newIndex <= oldIndex) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
          "Status can only move forward (todo → in-progress → done)."
      );
    }

    const updated: Task = { ...task, status: newStatus };
    this.store.set(id, updated);

    const payload: TaskStatusChangedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      oldStatus: task.status,
      newStatus,
    };
    this.bus.publish("task.statusChanged", payload);

    return updated;
  }
}

/**
 * Comment Service — owns all comment data.
 * Publishes "comment.added" via the Event Bus.
 * Depends on TaskService and UserService data only through the Router (ADR-002);
 * the event payload is enriched by the router before publishing.
 *
 * NOTE: To satisfy the "comment.added" event payload requirement
 * ({ commentId, taskId, taskTitle, authorId, authorName }), the router
 * passes taskTitle and authorName into the create() call so this service
 * can publish the fully-formed payload without importing other services.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
  /** Provided by the router after resolving the task — used for the event payload. */
  taskTitle: string;
  /** Provided by the router after resolving the author — used for the event payload. */
  authorName: string;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

export class CommentService {
  private readonly store = new Map<string, Comment>();
  private readonly bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(input: CreateCommentInput): Comment {
    if (!input.taskId) throw new Error("taskId is required");
    if (!input.authorId) throw new Error("authorId is required");
    if (!input.body || !input.body.trim()) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body.trim(),
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
    };
    this.bus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values())
      .filter((c) => c.taskId === taskId)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Notification Service — owns all notification data.
 * Subscribes to:
 *   - "task.assigned"      → notify the assignee
 *   - "task.statusChanged" → notify the assignee (if any)
 *   - "comment.added"      → notify the task's current assignee
 *
 * The service resolves which user to notify directly from the event payloads;
 * it does NOT call other services (ADR-001, ADR-002).
 * For "comment.added" the router enriches the event with the task's assigneeId
 * so this service can act on it without importing TaskService.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";
import {
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "./task-service.js";
import { CommentAddedPayload } from "./comment-service.js";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

/**
 * Extended comment.added payload that carries the task assigneeId so the
 * Notification Service knows whom to notify without querying TaskService.
 */
export interface CommentAddedWithAssigneePayload extends CommentAddedPayload {
  taskAssigneeId: string | null;
}

export class NotificationService {
  private readonly store = new Map<string, Notification>();

  constructor(bus: EventBus) {
    // task.assigned
    bus.subscribe("task.assigned", (raw) => {
      const payload = raw as TaskAssignedPayload;
      this.createNotification(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}" (${payload.taskId}).`
      );
    });

    // task.statusChanged
    bus.subscribe("task.statusChanged", (raw) => {
      const payload = raw as TaskStatusChangedPayload;
      if (!payload.assigneeId) return; // no one to notify
      this.createNotification(
        payload.assigneeId,
        `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`
      );
    });

    // comment.added — notify the task's current assignee (if any)
    bus.subscribe("comment.added", (raw) => {
      const payload = raw as CommentAddedWithAssigneePayload;
      if (!payload.taskAssigneeId) return;
      this.createNotification(
        payload.taskAssigneeId,
        `${payload.authorName} commented on task "${payload.taskTitle}": "${
          // Truncate very long bodies in the notification message
          payload.taskTitle
        }".`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values())
      .filter((n) => n.userId === userId)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new Error(`Notification not found: ${id}`);
    const updated: Notification = { ...notification, read: true };
    this.store.set(id, updated);
    return updated;
  }
}

/**
 * API Router — sole HTTP entry point.
 * Parses requests, delegates to the appropriate service method,
 * and serialises responses as JSON (ADR-003).
 *
 * Route table:
 *   GET    /users                        → UserService.getAll
 *   POST   /users                        → UserService.create
 *   GET    /users/:id                    → UserService.getById
 *   PUT    /users/:id                    → UserService.update
 *   DELETE /users/:id                    → UserService.delete
 *
 *   GET    /projects                     → ProjectService.getAll
 *   POST   /projects                     → ProjectService.create
 *   GET    /projects/:id                 → ProjectService.getById
 *   PUT    /projects/:id                 → ProjectService.update
 *   DELETE /projects/:id                 → ProjectService.delete
 *   POST   /projects/:id/members         → ProjectService.addMember
 *   DELETE /projects/:id/members         → ProjectService.removeMember
 *
 *   GET    /tasks?projectId=X            → TaskService.getByProject
 *   POST   /tasks                        → TaskService.create
 *   GET    /tasks/:id                    → TaskService.getById
 *   PUT    /tasks/:id                    → TaskService.update
 *   DELETE /tasks/:id                    → TaskService.delete
 *   PUT    /tasks/:id/status             → TaskService.changeStatus
 *   PUT    /tasks/:id/assign             → TaskService.assign
 *
 *   GET    /comments?taskId=X            → CommentService.getByTask
 *   POST   /comments                     → CommentService.create
 *   GET    /comments/:id                 → CommentService.getById
 *   DELETE /comments/:id                 → CommentService.delete
 *
 *   GET    /notifications?userId=X       → NotificationService.getByUser
 *   PUT    /notifications/:id/read       → NotificationService.markAsRead
 */

import { IncomingMessage, ServerResponse } from "http";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { CommentAddedWithAssigneePayload } from "./services/notification-service.js";

// ─── Helpers ────────────────────────────────────────────────────────────────

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      if (!raw) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function send(
  res: ServerResponse,
  status: number,
  data: unknown
): void {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function sendOk(res: ServerResponse, data: unknown): void {
  send(res, 200, data);
}

function sendCreated(res: ServerResponse, data: unknown): void {
  send(res, 201, data);
}

function sendError(res: ServerResponse, status: number, message: string): void {
  send(res, status, { error: message });
}

function getSearchParam(req: IncomingMessage, key: string): string | null {
  const url = new URL(req.url ?? "/", "http://localhost");
  return url.searchParams.get(key);
}

// ─── Route matching ──────────────────────────────────────────────────────────

interface RouteMatch {
  params: Record<string, string>;
}

/**
 * Tiny path matcher.
 * Pattern segments starting with ":" are captured as named params.
 * Returns null when the pathname does not match.
 */
function matchPath(
  pattern: string,
  pathname: string
): RouteMatch | null {
  const patternParts = pattern.split("/").filter(Boolean);
  const pathParts = pathname.split("/").filter(Boolean);

  if (patternParts.length !== pathParts.length) return null;

  const params: Record<string, string> = {};
  for (let i = 0; i < patternParts.length; i++) {
    const pp = patternParts[i];
    const vp = pathParts[i];
    if (pp.startsWith(":")) {
      params[pp.slice(1)] = vp;
    } else if (pp !== vp) {
      return null;
    }
  }
  return { params };
}

// ─── Router class ────────────────────────────────────────────────────────────

export class Router {
  private readonly users: UserService;
  private readonly projects: ProjectService;
  private readonly tasks: TaskService;
  private readonly comments: CommentService;
  private readonly notifications: NotificationService;

  constructor(
    users: UserService,
    projects: ProjectService,
    tasks: TaskService,
    comments: CommentService,
    notifications: NotificationService
  ) {
    this.users = users;
    this.projects = projects;
    this.tasks = tasks;
    this.comments = comments;
    this.notifications = notifications;
  }

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const method = req.method ?? "GET";
    const rawPath = new URL(req.url ?? "/", "http://localhost").pathname;
    // Normalise trailing slash
    const pathname = rawPath.endsWith("/") && rawPath !== "/"
      ? rawPath.slice(0, -1)
      : rawPath;

    try {
      await this.dispatch(method, pathname, req, res);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      // Map domain-style error messages to appropriate HTTP status codes
      const status = message.toLowerCase().includes("not found")
        ? 404
        : message.toLowerCase().includes("invalid")
        ? 400
        : message.toLowerCase().includes("already")
        ? 409
        : 400;
      sendError(res, status, message);
    }
  }

  private async dispatch(
    method: string,
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    let match: RouteMatch | null;

    // ── Users ──────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/users") {
      return sendOk(res, this.users.getAll());
    }

    if (method === "POST" && pathname === "/users") {
      const body = (await readBody(req)) as Record<string, unknown>;
      const user = this.users.create({
        name: String(body.name ?? ""),
        email: String(body.email ?? ""),
      });
      return sendCreated(res, user);
    }

    if ((match = matchPath("/users/:id", pathname))) {
      const { id } = match.params;
      if (method === "GET") return sendOk(res, this.users.getById(id));
      if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        return sendOk(res, this.users.update(id, {
          name: body.name !== undefined ? String(body.name) : undefined,
          email: body.email !== undefined ? String(body.email) : undefined,
        }));
      }
      if (method === "DELETE") {
        this.users.delete(id);
        return sendOk(res, { message: "User deleted" });
      }
    }

    // ── Projects ────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/projects") {
      return sendOk(res, this.projects.getAll());
    }

    if (method === "POST" && pathname === "/projects") {
      const body = (await readBody(req)) as Record<string, unknown>;
      const project = this.projects.create({
        name: String(body.name ?? ""),
        description: String(body.description ?? ""),
        memberIds: Array.isArray(body.memberIds)
          ? (body.memberIds as string[])
          : [],
      });
      return sendCreated(res, project);
    }

    if ((match = matchPath("/projects/:id/members", pathname))) {
      const { id } = match.params;
      const body = (await readBody(req)) as Record<string, unknown>;
      const userId = String(body.userId ?? "");
      if (method === "POST") {
        return sendOk(res, this.projects.addMember(id, userId));
      }
      if (method === "DELETE") {
        return sendOk(res, this.projects.removeMember(id, userId));
      }
    }

    if ((match = matchPath("/projects/:id", pathname))) {
      const { id } = match.params;
      if (method === "GET") return sendOk(res, this.projects.getById(id));
      if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        return sendOk(res, this.projects.update(id, {
          name: body.name !== undefined ? String(body.name) : undefined,
          description: body.description !== undefined
            ? String(body.description)
            : undefined,
        }));
      }
      if (method === "DELETE") {
        this.projects.delete(id);
        return sendOk(res, { message: "Project deleted" });
      }
    }

    // ── Tasks ───────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/tasks") {
      const projectId = getSearchParam(req, "projectId");
      if (projectId) {
        return sendOk(res, this.tasks.getByProject(projectId));
      }
      return sendOk(res, this.tasks.getAll());
    }

    if (method === "POST" && pathname === "/tasks") {
      const body = (await readBody(req)) as Record<string, unknown>;
      const task = this.tasks.create({
        title: String(body.title ?? ""),
        description: body.description !== undefined
          ? String(body.description)
          : undefined,
        projectId: String(body.projectId ?? ""),
        assigneeId: body.assigneeId !== undefined
          ? String(body.assigneeId)
          : undefined,
      });
      return sendCreated(res, task);
    }

    if ((match = matchPath("/tasks/:id/status", pathname))) {
      const { id } = match.params;
      if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const task = this.tasks.changeStatus(
          id,
          body.status as "todo" | "in-progress" | "done"
        );
        return sendOk(res, task);
      }
    }

    if ((match = matchPath("/tasks/:id/assign", pathname))) {
      const { id } = match.params;
      if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const task = this.tasks.assign(id, String(body.assigneeId ?? ""));
        return sendOk(res, task);
      }
    }

    if ((match = matchPath("/tasks/:id", pathname))) {
      const { id } = match.params;
      if (method === "GET") return sendOk(res, this.tasks.getById(id));
      if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        return sendOk(res, this.tasks.update(id, {
          title: body.title !== undefined ? String(body.title) : undefined,
          description: body.description !== undefined
            ? String(body.description)
            : undefined,
        }));
      }
      if (method === "DELETE") {
        this.tasks.delete(id);
        return sendOk(res, { message: "Task deleted" });
      }
    }

    // ── Comments ────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/comments") {
      const taskId = getSearchParam(req, "taskId");
      if (taskId) {
        return sendOk(res, this.comments.getByTask(taskId));
      }
      return sendError(res, 400, "taskId query parameter is required");
    }

    if (method === "POST" && pathname === "/comments") {
      const body = (await readBody(req)) as Record<string, unknown>;
      const taskId = String(body.taskId ?? "");
      const authorId = String(body.authorId ?? "");

      // Enrich the event payload — resolve task and author without storing
      // a cross-service reference (the router is the only place allowed to
      // talk to multiple services, ADR-002).
      const task = this.tasks.getById(taskId);
      const author = this.users.getById(authorId);

      const comment = this.comments.create({
        taskId,
        authorId,
        body: String(body.body ?? ""),
        taskTitle: task.title,
        authorName: author.name,
      });

      // Re-publish with the enriched payload so NotificationService can
      // notify the task's current assignee without querying TaskService itself.
      // NOTE: comment-service already published "comment.added"; we need the
      // assigneeId on that payload. We handle this by using a separate
      // enriched event shape that NotificationService already handles
      // (CommentAddedWithAssigneePayload). The CommentService publishes
      // the base payload; the router does NOT re-publish. Instead, the
      // NotificationService receives the base payload AND we pass assigneeId
      // as part of the published payload by having the CommentService accept
      // it. Let's adjust: we provide taskAssigneeId in the comment creation
      // so it gets included in the published event.
      //
      // Actually, the cleanest solution: the comment.added payload already
      // carries taskAssigneeId because we pass it through CreateCommentInput.
      // See comment-service.ts — we extended the payload. We just need to
      // ensure comment-service publishes it. Done below via a thin wrapper.
      //
      // This comment is left as an explanation. The actual enrichment is done
      // inside comment-service when taskAssigneeId is part of the input.
      void comment; // already returned
      return sendCreated(res, comment);
    }

    if ((match = matchPath("/comments/:id", pathname))) {
      const { id } = match.params;
      if (method === "GET") return sendOk(res, this.comments.getById(id));
      if (method === "DELETE") {
        this.comments.delete(id);
        return sendOk(res, { message: "Comment deleted" });
      }
    }

    // ── Notifications ───────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/notifications") {
      const userId = getSearchParam(req, "userId");
      if (!userId) return sendError(res, 400, "userId query parameter is required");
      return sendOk(res, this.notifications.getByUser(userId));
    }

    if ((match = matchPath("/notifications/:id/read", pathname))) {
      const { id } = match.params;
      if (method === "PUT") {
        return sendOk(res, this.notifications.markAsRead(id));
      }
    }

    // ── 404 fallback ────────────────────────────────────────────────────────
    sendError(res, 404, `Route not found: ${method} ${pathname}`);
  }
}

/**
 * Comment Service — owns all comment data.
 * Publishes "comment.added" via the Event Bus.
 *
 * The router enriches the create() input with taskTitle, authorName, and
 * taskAssigneeId (resolved by looking up the task and user) so this service
 * can publish a fully-formed event payload without importing other services
 * (ADR-001, ADR-002).
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
  /**
   * Resolved by the router from TaskService — used for the event payload.
   * Not stored on the comment record itself.
   */
  taskTitle: string;
  /**
   * Resolved by the router from UserService — used for the event payload.
   * Not stored on the comment record itself.
   */
  authorName: string;
  /**
   * Resolved by the router from TaskService — forwarded in the event so
   * NotificationService can notify the assignee without querying TaskService.
   * May be null if the task is unassigned.
   */
  taskAssigneeId: string | null;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
  /** Carried so NotificationService can resolve the notification recipient. */
  taskAssigneeId: string | null;
}

export class CommentService {
  private readonly store = new Map<string, Comment>();
  private readonly bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(input: CreateCommentInput): Comment {
    if (!input.taskId) throw new Error("taskId is required");
    if (!input.authorId) throw new Error("authorId is required");
    if (!input.body || !input.body.trim()) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body.trim(),
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
      taskAssigneeId: input.taskAssigneeId,
    };
    this.bus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values())
      .filter((c) => c.taskId === taskId)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Notification Service — owns all notification data.
 * Subscribes to:
 *   - "task.assigned"      → notify the assignee
 *   - "task.statusChanged" → notify the assignee (if any)
 *   - "comment.added"      → notify the task's current assignee (if any)
 *
 * All data needed to create a notification arrives in the event payload;
 * this service never calls or imports other services (ADR-001, ADR-002).
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";
import {
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "./task-service.js";
import { CommentAddedPayload } from "./comment-service.js";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

export class NotificationService {
  private readonly store = new Map<string, Notification>();

  constructor(bus: EventBus) {
    // ── task.assigned ──────────────────────────────────────────────────────
    bus.subscribe("task.assigned", (raw) => {
      const payload = raw as TaskAssignedPayload;
      this.createNotification(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}" (id: ${payload.taskId}).`
      );
    });

    // ── task.statusChanged ─────────────────────────────────────────────────
    bus.subscribe("task.statusChanged", (raw) => {
      const payload = raw as TaskStatusChangedPayload;
      if (!payload.assigneeId) return; // task is unassigned — nobody to notify
      this.createNotification(
        payload.assigneeId,
        `Task "${payload.taskTitle}" moved from "${payload.oldStatus}" to "${payload.newStatus}".`
      );
    });

    // ── comment.added ──────────────────────────────────────────────────────
    bus.subscribe("comment.added", (raw) => {
      const payload = raw as CommentAddedPayload;
      if (!payload.taskAssigneeId) return; // unassigned task — nobody to notify
      // Don't notify authors about their own comments
      if (payload.taskAssigneeId === payload.authorId) return;
      this.createNotification(
        payload.taskAssigneeId,
        `${payload.authorName} commented on task "${payload.taskTitle}".`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values())
      .filter((n) => n.userId === userId)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new Error(`Notification not found: ${id}`);
    const updated: Notification = { ...notification, read: true };
    this.store.set(id, updated);
    return updated;
  }
}

/**
 * API Router — sole HTTP entry point.
 * Parses requests, delegates to services, and serialises responses as JSON.
 * This is the only module that is permitted to reference multiple services
 * simultaneously (ADR-002). Services themselves never call each other.
 *
 * Route table:
 *   GET    /users                    UserService.getAll
 *   POST   /users                    UserService.create
 *   GET    /users/:id                UserService.getById
 *   PUT    /users/:id                UserService.update
 *   DELETE /users/:id                UserService.delete
 *
 *   GET    /projects                 ProjectService.getAll
 *   POST   /projects                 ProjectService.create
 *   GET    /projects/:id             ProjectService.getById
 *   PUT    /projects/:id             ProjectService.update
 *   DELETE /projects/:id             ProjectService.delete
 *   POST   /projects/:id/members     ProjectService.addMember
 *   DELETE /projects/:id/members     ProjectService.removeMember
 *
 *   GET    /tasks?projectId=X        TaskService.getByProject (or getAll)
 *   POST   /tasks                    TaskService.create
 *   GET    /tasks/:id                TaskService.getById
 *   PUT    /tasks/:id                TaskService.update
 *   DELETE /tasks/:id                TaskService.delete
 *   PUT    /tasks/:id/status         TaskService.changeStatus
 *   PUT    /tasks/:id/assign         TaskService.assign
 *
 *   GET    /comments?taskId=X        CommentService.getByTask
 *   POST   /comments                 CommentService.create
 *   GET    /comments/:id             CommentService.getById
 *   DELETE /comments/:id             CommentService.delete
 *
 *   GET    /notifications?userId=X   NotificationService.getByUser
 *   PUT    /notifications/:id/read   NotificationService.markAsRead
 */

import { IncomingMessage, ServerResponse } from "http";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService, TaskStatus } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";

// ─── HTTP helpers ─────────────────────────────────────────────────────────────

function readBody(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8").trim();
      if (!raw) {
        resolve({});
        return;
      }
      try {
        const parsed = JSON.parse(raw);
        resolve(typeof parsed === "object" && parsed !== null ? parsed : {});
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function send(res: ServerResponse, status: number, data: unknown): void {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

const sendOk = (res: ServerResponse, data: unknown) => send(res, 200, data);
const sendCreated = (res: ServerResponse, data: unknown) => send(res, 201, data);
const sendError = (res: ServerResponse, status: number, msg: string) =>
  send(res, status, { error: msg });

function queryParam(req: IncomingMessage, key: string): string | null {
  const url = new URL(req.url ?? "/", "http://localhost");
  return url.searchParams.get(key);
}

// ─── Path matching ────────────────────────────────────────────────────────────

interface RouteMatch {
  params: Record<string, string>;
}

/**
 * Match a URL pattern against a concrete pathname.
 * Pattern segments that start with ":" are treated as named captures.
 * Returns null when the pathname does not match.
 */
function matchPath(pattern: string, pathname: string): RouteMatch | null {
  const pp = pattern.split("/").filter(Boolean);
  const vp = pathname.split("/").filter(Boolean);
  if (pp.length !== vp.length) return null;

  const params: Record<string, string> = {};
  for (let i = 0; i < pp.length; i++) {
    if (pp[i].startsWith(":")) {
      params[pp[i].slice(1)] = vp[i];
    } else if (pp[i] !== vp[i]) {
      return null;
    }
  }
  return { params };
}

// Derive HTTP status from a thrown error message heuristic
function errorStatus(message: string): number {
  const m = message.toLowerCase();
  if (m.includes("not found")) return 404;
  if (m.includes("already")) return 409;
  if (m.includes("invalid") || m.includes("required") || m.includes("transition")) return 400;
  return 400;
}

// ─── Router ───────────────────────────────────────────────────────────────────

export class Router {
  constructor(
    private readonly users: UserService,
    private readonly projects: ProjectService,
    private readonly tasks: TaskService,
    private readonly comments: CommentService,
    private readonly notifications: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const method = (req.method ?? "GET").toUpperCase();
    // Strip trailing slash (except bare "/")
    const rawPath = new URL(req.url ?? "/", "http://localhost").pathname;
    const pathname =
      rawPath.length > 1 && rawPath.endsWith("/")
        ? rawPath.slice(0, -1)
        : rawPath;

    try {
      await this.dispatch(method, pathname, req, res);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      sendError(res, errorStatus(message), message);
    }
  }

  // eslint-disable-next-line complexity
  private async dispatch(
    method: string,
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    let m: RouteMatch | null;

    // ── Users ─────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/users") {
      return sendOk(res, this.users.getAll());
    }

    if (method === "POST" && pathname === "/users") {
      const body = await readBody(req);
      return sendCreated(res, this.users.create({
        name: String(body.name ?? ""),
        email: String(body.email ?? ""),
      }));
    }

    if ((m = matchPath("/users/:id", pathname))) {
      const { id } = m.params;
      if (method === "GET") return sendOk(res, this.users.getById(id));
      if (method === "PUT") {
        const body = await readBody(req);
        return sendOk(res, this.users.update(id, {
          name: body.name !== undefined ? String(body.name) : undefined,
          email: body.email !== undefined ? String(body.email) : undefined,
        }));
      }
      if (method === "DELETE") {
        this.users.delete(id);
        return sendOk(res, { message: "User deleted" });
      }
    }

    // ── Projects ──────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/projects") {
      return sendOk(res, this.projects.getAll());
    }

    if (method === "POST" && pathname === "/projects") {
      const body = await readBody(req);
      return sendCreated(res, this.projects.create({
        name: String(body.name ?? ""),
        description: String(body.description ?? ""),
        memberIds: Array.isArray(body.memberIds)
          ? (body.memberIds as string[])
          : [],
      }));
    }

    // /projects/:id/members must be matched BEFORE /projects/:id
    if ((m = matchPath("/projects/:id/members", pathname))) {
      const { id } = m.params;
      const body = await readBody(req);
      const userId = String(body.userId ?? "");
      if (method === "POST")
        return sendOk(res, this.projects.addMember(id, userId));
      if (method === "DELETE")
        return sendOk(res, this.projects.removeMember(id, userId));
    }

    if ((m = matchPath("/projects/:id", pathname))) {
      const { id } = m.params;
      if (method === "GET") return sendOk(res, this.projects.getById(id));
      if (method === "PUT") {
        const body = await readBody(req);
        return sendOk(res, this.projects.update(id, {
          name: body.name !== undefined ? String(body.name) : undefined,
          description:
            body.description !== undefined
              ? String(body.description)
              : undefined,
        }));
      }
      if (method === "DELETE") {
        this.projects.delete(id);
        return sendOk(res, { message: "Project deleted" });
      }
    }

    // ── Tasks ─────────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/tasks") {
      const projectId = queryParam(req, "projectId");
      return sendOk(
        res,
        projectId ? this.tasks.getByProject(projectId) : this.tasks.getAll()
      );
    }

    if (method === "POST" && pathname === "/tasks") {
      const body = await readBody(req);
      return sendCreated(res, this.tasks.create({
        title: String(body.title ?? ""),
        description:
          body.description !== undefined ? String(body.description) : undefined,
        projectId: String(body.projectId ?? ""),
        assigneeId:
          body.assigneeId !== undefined ? String(body.assigneeId) : undefined,
      }));
    }

    // /tasks/:id/status — match BEFORE /tasks/:id
    if ((m = matchPath("/tasks/:id/status", pathname))) {
      const { id } = m.params;
      if (method === "PUT") {
        const body = await readBody(req);
        return sendOk(
          res,
          this.tasks.changeStatus(id, body.status as TaskStatus)
        );
      }
    }

    // /tasks/:id/assign — match BEFORE /tasks/:id
    if ((m = matchPath("/tasks/:id/assign", pathname))) {
      const { id } = m.params;
      if (method === "PUT") {
        const body = await readBody(req);
        return sendOk(
          res,
          this.tasks.assign(id, String(body.assigneeId ?? ""))
        );
      }
    }

    if ((m = matchPath("/tasks/:id", pathname))) {
      const { id } = m.params;
      if (method === "GET") return sendOk(res, this.tasks.getById(id));
      if (method === "PUT") {
        const body = await readBody(req);
        return sendOk(res, this.tasks.update(id, {
          title: body.title !== undefined ? String(body.title) : undefined,
          description:
            body.description !== undefined
              ? String(body.description)
              : undefined,
        }));
      }
      if (method === "DELETE") {
        this.tasks.delete(id);
        return sendOk(res, { message: "Task deleted" });
      }
    }

    // ── Comments ──────────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/comments") {
      const taskId = queryParam(req, "taskId");
      if (!taskId)
        return sendError(res, 400, "taskId query parameter is required");
      return sendOk(res, this.comments.getByTask(taskId));
    }

    if (method === "POST" && pathname === "/comments") {
      const body = await readBody(req);
      const taskId = String(body.taskId ?? "");
      const authorId = String(body.authorId ?? "");

      // Resolve cross-service data here in the router (ADR-002):
      // CommentService needs taskTitle, authorName, and taskAssigneeId for
      // the event payload but must not import TaskService or UserService.
      const task = this.tasks.getById(taskId);
      const author = this.users.getById(authorId);

      return sendCreated(res, this.comments.create({
        taskId,
        authorId,
        body: String(body.body ?? ""),
        taskTitle: task.title,
        authorName: author.name,
        taskAssigneeId: task.assigneeId,
      }));
    }

    if ((m = matchPath("/comments/:id", pathname))) {
      const { id } = m.params;
      if (method === "GET") return sendOk(res, this.comments.getById(id));
      if (method === "DELETE") {
        this.comments.delete(id);
        return sendOk(res, { message: "Comment deleted" });
      }
    }

    // ── Notifications ─────────────────────────────────────────────────────

    if (method === "GET" && pathname === "/notifications") {
      const userId = queryParam(req, "userId");
      if (!userId)
        return sendError(res, 400, "userId query parameter is required");
      return sendOk(res, this.notifications.getByUser(userId));
    }

    if ((m = matchPath("/notifications/:id/read", pathname))) {
      const { id } = m.params;
      if (method === "PUT")
        return sendOk(res, this.notifications.markAsRead(id));
    }

    // ── 404 ───────────────────────────────────────────────────────────────
    sendError(res, 404, `Route not found: ${method} ${pathname}`);
  }
}

/**
 * Entry point — wires all services together and starts the HTTP server.
 *
 * Construction order matters:
 *   1. Create the EventBus singleton.
 *   2. Instantiate services that subscribe to events (NotificationService)
 *      so subscriptions are registered before any events are published.
 *   3. Instantiate services that publish events (TaskService, CommentService).
 *   4. Build the Router with all service instances.
 *   5. Start the HTTP server.
 */

import { createServer } from "http";
import { eventBus } from "./event-bus.js";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { Router } from "./router.js";

const PORT = Number(process.env.PORT ?? 3000);
const HOST = process.env.HOST ?? "127.0.0.1";

// Instantiate services ──────────────────────────────────────────────────────
const userService = new UserService();
const projectService = new ProjectService();

// NotificationService subscribes in its constructor — must be created before
// TaskService / CommentService start publishing.
const notificationService = new NotificationService(eventBus);

const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);

// Wire router ───────────────────────────────────────────────────────────────
const router = new Router(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

// Start server ──────────────────────────────────────────────────────────────
const server = createServer((req, res) => {
  router.handle(req, res).catch((err) => {
    console.error("[Server] Unhandled error:", err);
    if (!res.headersSent) {
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Internal server error" }));
    }
  });
});

server.listen(PORT, HOST, () => {
  console.log(`Task Management API listening on http://${HOST}:${PORT}`);
});

export { userService, projectService, taskService, commentService, notificationService };

/**
 * Demo script — exercises every feature of the Task Management API.
 *
 * Flow:
 *   1.  Start the HTTP server (in-process, same port as main.ts)
 *   2.  Create two users (Alice, Bob)
 *   3.  Create a project and add both users as members
 *   4.  Create two tasks in that project
 *   5.  Assign a task to Alice  → triggers task.assigned notification
 *   6.  Change task status (todo → in-progress → done)  → triggers notifications
 *   7.  Add comments by Bob on the assigned task  → triggers comment notifications
 *   8.  Read notifications for Alice
 *   9.  Mark a notification as read
 *   10. Exercise remaining CRUD routes (update user/project/task, delete comment)
 *   11. Verify that an invalid status transition is rejected
 *   12. Shut down gracefully
 */

import { createServer, IncomingMessage, ServerResponse } from "http";
import { eventBus } from "./event-bus.js";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { Router } from "./router.js";

// ─── Bootstrap ───────────────────────────────────────────────────────────────

const PORT = 3001; // use a separate port so demo doesn't conflict with main.ts
const BASE = `http://127.0.0.1:${PORT}`;

const userService = new UserService();
const projectService = new ProjectService();
const notificationService = new NotificationService(eventBus);
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);

const router = new Router(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

const server = createServer((req: IncomingMessage, res: ServerResponse) => {
  router.handle(req, res).catch((err) => {
    console.error("[Server] Unhandled:", err);
    if (!res.headersSent) {
      res.writeHead(500);
      res.end(JSON.stringify({ error: "Internal server error" }));
    }
  });
});

// ─── HTTP client helper ───────────────────────────────────────────────────────

interface ApiResponse<T = unknown> {
  status: number;
  body: T;
}

function request<T = unknown>(
  method: string,
  path: string,
  payload?: unknown
): Promise<ApiResponse<T>> {
  return new Promise((resolve, reject) => {
    const bodyStr = payload !== undefined ? JSON.stringify(payload) : undefined;
    const url = new URL(path, BASE);

    const req = (await import("http")).default
      ? null // never used, just satisfies the import path for type inference
      : null;
    void req;

    const nodeReq = (require("http") as typeof import("http")).request(
      {
        hostname: url.hostname,
        port: Number(url.port),
        path: url.pathname + url.search,
        method,
        headers: {
          "Content-Type": "application/json",
          ...(bodyStr ? { "Content-Length": Buffer.byteLength(bodyStr) } : {}),
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () => {
          try {
            const body = JSON.parse(Buffer.concat(chunks).toString("utf8")) as T;
            resolve({ status: res.statusCode ?? 0, body });
          } catch {
            reject(new Error("Failed to parse response JSON"));
          }
        });
      }
    );
    nodeReq.on("error", reject);
    if (bodyStr) nodeReq.write(bodyStr);
    nodeReq.end();
  });
}

