// ─── Demo ─────────────────────────────────────────────────────────────────────

async function run() {
  // ── 1. Users ────────────────────────────────────────────────────────────
  section("1. Create users");

  const aliceRes = await request<Record<string, unknown>>("POST", "/users", {
    name: "Alice",
    email: "alice@example.com",
  });
  assert(aliceRes.status === 201, "Create Alice", aliceRes.body);
  const alice = aliceRes.body;

  const bobRes = await request<Record<string, unknown>>("POST", "/users", {
    name: "Bob",
    email: "bob@example.com",
  });
  assert(bobRes.status === 201, "Create Bob", bobRes.body);
  const bob = bobRes.body;

  const allUsersRes = await request<unknown[]>("GET", "/users");
  assert(allUsersRes.status === 200, "GET /users", allUsersRes.body);
  assert(
    Array.isArray(allUsersRes.body) && allUsersRes.body.length === 2,
    "Two users exist"
  );

  const getUserRes = await request("GET", `/users/${alice.id}`);
  assert(getUserRes.status === 200, `GET /users/${alice.id}`, getUserRes.body);

  const updateUserRes = await request<Record<string, unknown>>(
    "PUT",
    `/users/${alice.id}`,
    { name: "Alice A." }
  );
  assert(
    updateUserRes.status === 200 && updateUserRes.body.name === "Alice A.",
    "Update Alice's name",
    updateUserRes.body
  );

  // ── 2. Project ──────────────────────────────────────────────────────────
  section("2. Create project");

  const projRes = await request<Record<string, unknown>>("POST", "/projects", {
    name: "Apollo",
    description: "Mission to ship v1",
  });
  assert(projRes.status === 201, "Create project Apollo", projRes.body);
  const project = projRes.body;

  const updateProjRes = await request<Record<string, unknown>>(
    "PUT",
    `/projects/${project.id}`,
    { description: "Mission to ship v1.0" }
  );
  assert(
    updateProjRes.status === 200,
    "Update project description",
    updateProjRes.body
  );

  // ── 3. Add members ──────────────────────────────────────────────────────
  section("3. Add members to project");

  const addAliceRes = await request<Record<string, unknown>>(
    "POST",
    `/projects/${project.id}/members`,
    { userId: alice.id }
  );
  assert(
    addAliceRes.status === 200 &&
      Array.isArray(addAliceRes.body.memberIds) &&
      (addAliceRes.body.memberIds as string[]).includes(alice.id as string),
    "Add Alice to project",
    addAliceRes.body
  );

  const addBobRes = await request<Record<string, unknown>>(
    "POST",
    `/projects/${project.id}/members`,
    { userId: bob.id }
  );
  assert(
    addBobRes.status === 200,
    "Add Bob to project",
    addBobRes.body
  );

  // Duplicate member should fail
  const dupRes = await request(
    "POST",
    `/projects/${project.id}/members`,
    { userId: alice.id }
  );
  assert(dupRes.status === 409, "Duplicate member returns 409", dupRes.body);

  // ── 4. Create tasks ─────────────────────────────────────────────────────
  section("4. Create tasks");

  const task1Res = await request<Record<string, unknown>>("POST", "/tasks", {
    title: "Design database schema",
    description: "ERD for all entities",
    projectId: project.id,
  });
  assert(task1Res.status === 201, "Create task 1", task1Res.body);
  const task1 = task1Res.body;

  const task2Res = await request<Record<string, unknown>>("POST", "/tasks", {
    title: "Implement API router",
    description: "HTTP routing layer",
    projectId: project.id,
  });
  assert(task2Res.status === 201, "Create task 2", task2Res.body);
  const task2 = task2Res.body;

  const byProjectRes = await request<unknown[]>(
    "GET",
    `/tasks?projectId=${project.id}`
  );
  assert(
    byProjectRes.status === 200 && (byProjectRes.body as unknown[]).length === 2,
    "GET /tasks?projectId returns 2 tasks",
    byProjectRes.body
  );

  const getTaskRes = await request("GET", `/tasks/${task1.id}`);
  assert(getTaskRes.status === 200, `GET /tasks/${task1.id}`, getTaskRes.body);

  const updateTaskRes = await request<Record<string, unknown>>(
    "PUT",
    `/tasks/${task1.id}`,
    { title: "Design DB schema (v2)" }
  );
  assert(
    updateTaskRes.status === 200,
    "Update task title",
    updateTaskRes.body
  );

  // ── 5. Assign tasks ─────────────────────────────────────────────────────
  section("5. Assign tasks → task.assigned event → notification");

  info("Assigning task 1 to Alice…");
  const assignRes = await request<Record<string, unknown>>(
    "PUT",
    `/tasks/${task1.id}/assign`,
    { assigneeId: alice.id }
  );
  assert(
    assignRes.status === 200 && assignRes.body.assigneeId === alice.id,
    "Assign task 1 to Alice",
    assignRes.body
  );

  info("Assigning task 2 to Alice…");
  const assign2Res = await request<Record<string, unknown>>(
    "PUT",
    `/tasks/${task2.id}/assign`,
    { assigneeId: alice.id }
  );
  assert(assign2Res.status === 200, "Assign task 2 to Alice", assign2Res.body);

  const notifsAfterAssign = await request<unknown[]>(
    "GET",
    `/notifications?userId=${alice.id}`
  );
  assert(
    notifsAfterAssign.status === 200 &&
      (notifsAfterAssign.body as unknown[]).length >= 2,
    "Alice has ≥ 2 notifications after assignments",
    notifsAfterAssign.body
  );

  // ── 6. Status transitions ───────────────────────────────────────────────
  section("6. Task status transitions → task.statusChanged → notifications");

  const toInProgressRes = await request<Record<string, unknown>>(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "in-progress" }
  );
  assert(
    toInProgressRes.status === 200 &&
      toInProgressRes.body.status === "in-progress",
    "task1: todo → in-progress",
    toInProgressRes.body
  );

  const toDoneRes = await request<Record<string, unknown>>(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "done" }
  );
  assert(
    toDoneRes.status === 200 && toDoneRes.body.status === "done",
    "task1: in-progress → done",
    toDoneRes.body
  );

  // Backward transition should fail
  info("Attempting invalid backward transition (done → todo)…");
  const badTransitionRes = await request(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "todo" }
  );
  assert(
    badTransitionRes.status === 400,
    "Backward transition rejected with 400",
    badTransitionRes.body
  );

  // Skip a step should also fail
  info("Attempting invalid skip transition (todo → done)…");
  const skipTransitionRes = await request(
    "PUT",
    `/tasks/${task2.id}/status`,
    { status: "done" }
  );
  assert(
    skipTransitionRes.status === 400,
    "Skip transition rejected with 400",
    skipTransitionRes.body
  );

  // ── 7. Comments ─────────────────────────────────────────────────────────
  section("7. Comments → comment.added event → notifications");

  const comment1Res = await request<Record<string, unknown>>(
    "POST",
    "/comments",
    {
      taskId: task2.id,
      authorId: bob.id,
      body: "Hey Alice, do you need help with the router?",
    }
  );
  assert(comment1Res.status === 201, "Bob comments on task 2", comment1Res.body);
  const comment1 = comment1Res.body;

  const comment2Res = await request<Record<string, unknown>>(
    "POST",
    "/comments",
    {
      taskId: task2.id,
      authorId: bob.id,
      body: "I can pair with you on the path matching logic.",
    }
  );
  assert(comment2Res.status === 201, "Bob adds second comment", comment2Res.body);

  const commentsByTaskRes = await request<unknown[]>(
    "GET",
    `/comments?taskId=${task2.id}`
  );
  assert(
    commentsByTaskRes.status === 200 &&
      (commentsByTaskRes.body as unknown[]).length === 2,
    "GET /comments?taskId returns 2 comments",
    commentsByTaskRes.body
  );

  const getCommentRes = await request(
    "GET",
    `/comments/${comment1.id}`
  );
  assert(
    getCommentRes.status === 200,
    `GET /comments/${comment1.id}`,
    getCommentRes.body
  );

  // ── 8. Notifications ────────────────────────────────────────────────────
  section("8. Check Alice's notifications");

  const aliceNotifsRes = await request<Array<Record<string, unknown>>>(
    "GET",
    `/notifications?userId=${alice.id}`
  );
  assert(
    aliceNotifsRes.status === 200,
    `GET /notifications?userId=${alice.id}`,
    aliceNotifsRes.body
  );
  const aliceNotifs = aliceNotifsRes.body;
  assert(
    aliceNotifs.length >= 4,
    `Alice has ≥ 4 notifications (2 assign + 2 statusChanged + 2 comments)`,
    { count: aliceNotifs.length }
  );

  const unreadCount = aliceNotifs.filter((n) => !n.read).length;
  assert(unreadCount === aliceNotifs.length, "All notifications are unread");

  // ── 9. Mark notification as read ────────────────────────────────────────
  section("9. Mark notification as read");

  const firstNotifId = aliceNotifs[0].id as string;
  const markReadRes = await request<Record<string, unknown>>(
    "PUT",
    `/notifications/${firstNotifId}/read`
  );
  assert(
    markReadRes.status === 200 && markReadRes.body.read === true,
    "Notification marked as read",
    markReadRes.body
  );

  const afterMarkRes = await request<Array<Record<string, unknown>>>(
    "GET",
    `/notifications?userId=${alice.id}`
  );
  const stillUnread = (afterMarkRes.body as Array<Record<string, unknown>>).filter(
    (n) => !n.read
  ).length;
  assert(
    stillUnread === aliceNotifs.length - 1,
    `Unread count decreased by 1 (now ${stillUnread})`
  );

  // ── 10. Remove member ───────────────────────────────────────────────────
  section("10. Remove Bob from project");

  const removeBobRes = await request<Record<string, unknown>>(
    "DELETE",
    `/projects/${project.id}/members`,
    { userId: bob.id }
  );
  assert(
    removeBobRes.status === 200 &&
      !(removeBobRes.body.memberIds as string[]).includes(bob.id as string),
    "Remove Bob from project",
    removeBobRes.body
  );

  // ── 11. Delete comment ──────────────────────────────────────────────────
  section("11. Delete a comment");

  const delCommentRes = await request(
    "DELETE",
    `/comments/${comment1.id}`
  );
  assert(delCommentRes.status === 200, "Delete comment 1", delCommentRes.body);

  const afterDeleteRes = await request<unknown[]>(
    "GET",
    `/comments?taskId=${task2.id}`
  );
  assert(
    (afterDeleteRes.body as unknown[]).length === 1,
    "Only 1 comment remains after deletion"
  );

  // ── 12. 404 / error paths ───────────────────────────────────────────────
  section("12. Error handling");

  const notFoundRes = await request("GET", "/users/no-such-id");
  assert(notFoundRes.status === 404, "Unknown user returns 404", notFoundRes.body);

  const badRouteRes = await request("GET", "/unknown-route");
  assert(badRouteRes.status === 404, "Unknown route returns 404", badRouteRes.body);

  const missingBodyRes = await request("POST", "/users", {
    name: "",
    email: "",
  });
  assert(
    missingBodyRes.status === 400,
    "Create user with empty fields returns 400",
    missingBodyRes.body
  );

  const missingUserIdRes = await request("GET", "/notifications");
  assert(
    missingUserIdRes.status === 400,
    "GET /notifications without userId returns 400",
    missingUserIdRes.body
  );

  // ── 13. DELETE task and project ─────────────────────────────────────────
  section("13. Clean up — delete task and project");

  const delTask2Res = await request("DELETE", `/tasks/${task2.id}`);
  assert(delTask2Res.status === 200, "Delete task 2", delTask2Res.body);

  const delProjRes = await request("DELETE", `/projects/${project.id}`);
  assert(delProjRes.status === 200, "Delete project", delProjRes.body);

  const allProjRes = await request<unknown[]>("GET", "/projects");
  assert(
    (allProjRes.body as unknown[]).length === 0,
    "No projects remain",
    allProjRes.body
  );

  // ── Summary ─────────────────────────────────────────────────────────────
  section("Demo complete");
  if (process.exitCode === 1) {
    console.log(`\n${RED}${BOLD}Some assertions failed.${RESET}\n`);
  } else {
    console.log(`\n${GREEN}${BOLD}All assertions passed ✓${RESET}\n`);
  }
}

// ─── Start ────────────────────────────────────────────────────────────────────

server.listen(PORT, "127.0.0.1", async () => {
  console.log(`${BOLD}Task Management API — Demo${RESET}`);
  console.log(`Server listening on ${BASE}\n`);
  try {
    await run();
  } catch (err) {
    console.error(`${RED}Unexpected error:${RESET}`, err);
    process.exitCode = 1;
  } finally {
    server.close();
  }
});

/**
 * Demo script — exercises every feature of the Task Management API.
 *
 * Flow:
 *   1.  Start the HTTP server (in-process)
 *   2.  Create two users (Alice, Bob)
 *   3.  Create a project and add both users as members
 *   4.  Create two tasks in that project
 *   5.  Assign tasks to Alice       → task.assigned event → notifications
 *   6.  Change task status          → task.statusChanged event → notifications
 *   7.  Bob adds comments on a task → comment.added event → notifications
 *   8.  Read Alice's notifications
 *   9.  Mark a notification as read
 *   10. Remove member, delete comment, delete task, delete project
 *   11. Verify invalid status transitions are rejected
 *   12. Verify 404 / error responses
 */

